head.script:
// 시장지 결과조회

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.stf.setFromToDate(1, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20600.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20600.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_SDATE_onclick
 * @description img_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20600.img_SDATE_onclick" });
    }
};

/**
 * @method
 * @name img_EDATE_onclick
 * @description img_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20600.img_EDATE_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        // alert('dts_List.OnLoadCompleted('+rowcount+')');
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }

        txa_SECURPT_BINFILE.text = "";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20600.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        if (row === 0) return;
        const SECURPT_TP_CD = dts_List.getCellData(row, "SECURPT_TP_CD");
        const TRD_DD = dts_List.getCellData(row, "TRD_DD");
        await scwin.ins_detail(TRD_DD, SECURPT_TP_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20600.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name dts_Rst_OnLoadCompleted
 * @description dts_Rst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Rst_OnLoadCompleted = function(rowcount) {
    // alert('dts_Rst.OnLoadCompleted('+rowcount+')');

};

/**
 * @method
 * @name trs_modify_OnFail
 * @description modify On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_modify_OnFail = function() {
    try {
        alert_tr_error(trs_modify);
        // alert('trs_modify.OnFail()');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20600.trs_modify_OnFail" });
    }
};

/**
 * @method
 * @name trs_modify_OnSuccess
 * @description modify On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_modify_OnSuccess = function() {
    // alert('trs_modify.OnSuccess()');

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 시장지 결과  조회한다. TBLD_B_SECURPT_FILE
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }
    // alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_detail
 * @description 시장지 결과 상세 조회한다.
 * @param {String} TRD_DD TRD_DD
 * @param {String} SECURPT_TP_CD SECURPT_TP_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_detail = async function(TRD_DD, SECURPT_TP_CD) {
    trs_modify.KeyName = "toinb_dataid4";
    // trs_modify.Parameters    = "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email ;
    const sbmOptions = {
        id : "sbm_trs_modify",
        action : "/EtcInfoAction.do",
        ref : "dts_Rst",
        target : "trs_modify=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};
